 9	    /**
10	     * Returns true when an array contains two values that add up to the target.
11	     * The input is not mutated; a sorted copy is used internally.
12	     */
13	    static boolean hasPairWithSum(int[] values, int target) {
14	        if (values == null || values.length < 2) {
15	            return false;
16	        }
17	
18	        int[] sortedValues = values.clone();
19	        Arrays.sort(sortedValues);
20	        return hasPairWithSumSorted(sortedValues, target);
21	    }
22	
23	    /**
24	     * Two-pointer search over an already sorted array.
25	     */
26	    static boolean hasPairWithSumSorted(int[] sortedValues, int target) {
27	        if (sortedValues == null || sortedValues.length < 2) {
28	            return false;
29	        }
30	
31	        int left = 0;
32	        int right = sortedValues.length - 1;
33	
34	        while (left < right) {
35	            long sum = (long) sortedValues[left] + sortedValues[right];
36	
37	            if (sum == target) {
38	                return true;
39	            }
40	
41	            if (sum < target) {
42	                left++;
43	            } else {
44	                right--;
45	            }
46	        }
47	
48	        return false;
49	    }
50	}

